  function reminderForm(id=''){const old=id?state.reminders.find(r=>r.id===id):null;if(id&&!old)return;const r=old||{id:G.id(),title:'',at:G.today()+'T',enabled:true};showModal(old?'تعديل التذكير':'تذكير خاص جديد',`<p class="explain">سيصدر المنبه في الموعد المحدد. عنوان التذكير يظهر داخل التطبيق فقط.</p><div class="form-grid"><div class="field full"><label for="f-title">بماذا نذكّرك؟ *</label><input id="f-title" name="title" maxlength="300" value="${e(r.title)}" placeholder="مثال: تجهيز بطاقات الجلسة" required></div>${field('التاريخ *','date',r.at.slice(0,10),'date','required min="2000-01-01" max="2100-12-31"')}${field('الوقت · غزة *','time',r.at.slice(11,16),'time','required step="60"')}</div><label class="check-row"><input name="enabled" type="checkbox" ${r.enabled?'checked':''}>تشغيل التذكير</label>`,saveFooter(old?'حفظ التذكير':'إضافة التذكير'),form=>{const next={...r,title:value(form,'title'),at:value(form,'date')+'T'+value(form,'time'),enabled:form.elements.enabled.checked};if(!next.title)throw Error('اكتبي عنوانًا للتذكير.');if(G.toEpoch(next.at)<=0)throw Error('تحققي من التاريخ والوقت بتوقيت غزة.');if(next.enabled&&G.toEpoch(next.at)<=Date.now())throw Error('اختاري موعدًا في المستقبل لتشغيل التذكير.');commit(d=>{if(old)d.reminders[d.reminders.findIndex(x=>x.id===id)]=next;else d.reminders.push(next);},old?'تم تحديث التذكير':'أُضيف التذكير بنجاح');});}
